WAVE_TEMPLATE = {
  north = {
    top = {
      Name = "Custom_Token",
      Transform = {
        posX = 0,
        posY = 1.6,
        posZ = 0,
        rotX = 0,
        rotY = 180,
        rotZ = 0,
        scaleX = 1,
        scaleY = 1,
        scaleZ = 1
      },
      Nickname = "Blue top wave",
      Description = "Minion wave: chips = HP. Left-click -1 (the clicker's team banks 1 AP), right-click +1.",
      GMNotes = "hn:wave:template",
      ColorDiffuse = {
        r = 1,
        g = 1,
        b = 1
      },
      Locked = false,
      Grid = false,
      Snap = true,
      IgnoreFoW = false,
      Autoraise = true,
      Sticky = true,
      Tooltip = true,
      GridProjection = false,
      HideWhenFaceDown = false,
      Hands = false,
      LuaScript = "-- Hex-Nexus HP counter: champions, towers, the Nexus, monsters and waves.\n-- Left-click removes 1, right-click adds 1. The Global script hears every\n-- change (hnCounterChanged): it banks AP for chips, handles kills, falls and\n-- rewards. Starting numbers come from the exporter, never from this file.\nlocal st = {}\n\nfunction onLoad(saved)\n  local ok, t = pcall(JSON.decode, saved or \"\")\n  if ok and type(t) == \"table\" then st = t end\n  st.hp = st.hp or 0\n  st.max = st.max or st.hp\n  draw()\nend\n\nfunction onSave() return JSON.encode(st) end\n\nfunction hnGet() return st end\n\nfunction hnSet(t)\n  for k, v in pairs(t or {}) do st[k] = v end\n  draw()\nend\n\nlocal function label()\n  if st.kind == \"champion\" then\n    if st.hp <= 0 then return \"DEAD\" end\n    return st.hp .. \"/\" .. st.max\n  elseif st.kind == \"structure\" then\n    if st.hp <= 0 then return \"destroyed\" end\n    return st.hp .. \" (min \" .. (st.floor or 0) .. \")\"\n  elseif st.kind == \"monster\" and st.hp <= 0 then\n    return \"down · R\" .. (st.respawn_round or \"?\")\n  end\n  return tostring(st.hp)\nend\n\nfunction draw()\n  self.clearButtons()\n  local s = self.getScale()\n  local k = 1 / math.max(s.x, 0.01)\n  -- local half-depth of the token, so the label sits on its lower edge\n  -- (local +z is the bottom of the image) and leaves the art readable\n  local b = self.getBoundsNormalized()\n  local half = 0.5\n  if b and b.size and s.z > 0 then half = b.size.z / s.z / 2 end\n  local colour = {0, 0, 0, 0.75}\n  if st.kind == \"champion\" and st.hp > st.max then colour = {0.55, 0.42, 0.05, 0.85} end\n  if st.hp <= 0 then colour = {0.45, 0.05, 0.05, 0.85} end\n  local text = label()\n  self.createButton({\n    click_function = \"hnClick\", function_owner = self, label = text,\n    position = {0, 0.2, half * 0.72}, rotation = {0, 0, 0}, scale = {k * 0.5, 1, k * 0.5},\n    width = 110 * #text + 160, height = 260, font_size = 200,\n    color = colour, font_color = {1, 1, 1},\n    tooltip = (st.label or \"\") .. \": left-click -1, right-click +1\",\n  })\nend\n\nfunction hnClick(_, player_colour, alt)\n  local before = st.hp\n  st.hp = math.max(0, st.hp + (alt and 1 or -1))\n  draw()\n  if st.hp ~= before then\n    Global.call(\"hnCounterChanged\", {guid = self.getGUID(), before = before, after = st.hp,\n                                     colour = player_colour})\n  end\nend\n",
      LuaScriptState = "",
      XmlUI = "",
      CustomImage = {
        ImageURL = "https://raw.githubusercontent.com/Noitues/Games/claude/tts-mod-builder/tts/build/assets/wave_north_top.png?v=748d9e01bd",
        ImageSecondaryURL = "",
        ImageScalar = 1,
        WidthScale = 0,
        CustomToken = {
          Thickness = 0.3,
          MergeDistancePixels = 15,
          StandUp = false,
          Stackable = false
        }
      }
    },
    mid = {
      Name = "Custom_Token",
